package dev.thefoolish.generated.anishelf;import android.content.*;import java.util.*;public final class RepositoryStore{private final SharedPreferences p;public RepositoryStore(Context c){p=c.getSharedPreferences("extension_repositories",0);}public java.util.List<String> all(){return new ArrayList<>(p.getStringSet("urls",new LinkedHashSet<>()));}public boolean add(String raw){String u=raw==null?"":raw.trim();if(!u.startsWith("https://"))return false;Set<String>s=new LinkedHashSet<>(p.getStringSet("urls",new LinkedHashSet<>()));boolean n=s.add(u);p.edit().putStringSet("urls",s).apply();return n;}public void remove(String u){Set<String>s=new LinkedHashSet<>(p.getStringSet("urls",new LinkedHashSet<>()));s.remove(u);p.edit().putStringSet("urls",s).apply();}}
